	/*
     * @param	event CreateSupplierEvent
     */
    @EventHandler( payloadType=CreateSupplierEvent.class )
    public void handle( CreateSupplierEvent event) {
	    LOGGER.info("handling CreateSupplierEvent - " + event );
	    Supplier entity = new Supplier();
            entity.setSupplierId( event.getSupplierId() );
            entity.setName( event.getName() );
            entity.setContactEmail( event.getContactEmail() );
            entity.setWebsite( event.getWebsite() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSupplier( entity );
    }

    /*
     * @param	event UpdateSupplierEvent
     */
    @EventHandler( payloadType=UpdateSupplierEvent.class )
    public void handle( UpdateSupplierEvent event) {
    	LOGGER.info("handling UpdateSupplierEvent - " + event );
    	
	    Supplier entity = new Supplier();
            entity.setSupplierId( event.getSupplierId() );
            entity.setName( event.getName() );
            entity.setContactEmail( event.getContactEmail() );
            entity.setWebsite( event.getWebsite() );
            entity.setMerchant( event.getMerchant() );
            entity.setProducts( event.getProducts() );
            entity.setFulfillmentCenters( event.getFulfillmentCenters() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindSupplier( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSupplier( entity );        
    }
    
